// src/viewmodels/hooks/useSignup.js - VERSION AMÉLIORÉE
import { useState } from 'react';
import { projectAuth, projectStorage, projectFirestore } from '../../models/services/firebase/config';
import { useAuthContext } from './useAuthContext';

export const useSignup = () => {
  const [error, setError] = useState(null);
  const [isPending, setIsPending] = useState(false);
  const { dispatch } = useAuthContext();

  const signup = async (email, password, displayName, thumbnail) => {
    setError(null);
    setIsPending(true);

    try {
      console.log('1. Début de la création du compte...');

      // 1. Création de l'utilisateur dans Firebase Auth
      const res = await projectAuth.createUserWithEmailAndPassword(email, password);
      console.log('2. Compte Auth créé:', res.user.uid);

      if (!res.user) throw new Error('Impossible de créer le compte');

      // 2. Upload de la photo de profil (si elle existe)
      let photoURL = null;
      if (thumbnail) {
        console.log('3. Upload de la photo...');
        const uploadPath = `thumbnails/${res.user.uid}/${thumbnail.name}`;
        const img = await projectStorage.ref(uploadPath).put(thumbnail);
        photoURL = await img.ref.getDownloadURL();
        console.log('4. Photo uploadée:', photoURL);
      }

      // 3. Mise à jour du profil Firebase Auth
      console.log('5. Mise à jour du profil Auth...');
      await res.user.updateProfile({
        displayName,
        photoURL
      });

      // 4. Création du document utilisateur dans Firestore - COLLECTION UNIQUE 'users'
      console.log('6. Création dans Firestore...');
      try {
        await projectFirestore.collection('users').doc(res.user.uid).set({
          uid: res.user.uid,
          email: email,
          displayName: displayName,
          photoURL: photoURL,
          role: 'student',
          createdAt: new Date(),
          lastLogin: new Date(),
          status: 'active',
          preferences: {}
        });
        console.log('✅ Document créé dans Firestore collection "users"');
      } catch (firestoreErr) {
        console.error("❌ Erreur Firestore:", firestoreErr);
        // Annuler la création du compte Auth si Firestore échoue ?
        // await res.user.delete(); // Option: supprimer l'utilisateur Auth
        throw new Error('Échec de la création du profil: ' + firestoreErr.message);
      }

      // 5. Rafraîchir l'utilisateur pour obtenir les données mises à jour
      await res.user.reload();
      const currentUser = projectAuth.currentUser;

      // 6. Mise à jour du contexte d'authentification
      console.log('7. Mise à jour du contexte...');
      dispatch({ type: 'LOGIN', payload: currentUser });

      setIsPending(false);
      return true;

    } catch (err) {
      console.error('❌ Erreur complète lors du signup:', err.code, err.message);
      setError(err.message);
      setIsPending(false);
      return false;
    }
  };

  return { signup, isPending, error };
};
